package com.tainted.authuser.blackbox;

import io.lettuce.core.RedisClient;
import io.lettuce.core.api.StatefulRedisConnection;
import io.restassured.http.ContentType;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestInfo;
import org.junit.jupiter.api.TestInstance;
import org.junit.jupiter.api.parallel.Execution;
import org.junit.jupiter.api.parallel.ExecutionMode;

import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.util.Map;

import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.containsString;
import static org.hamcrest.Matchers.equalTo;
import static org.hamcrest.Matchers.matchesPattern;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Black-Box API Integration Test
 *
 * @target-controller AuthController (src/main/java/com/tainted/authuser/web/AuthController.java)
 * @target-api POST /api/v1/auth/login
 *
 * No WireMock stubs: detect-external-calls (--include-di-analysis) found zero external HTTP
 * calls reachable from this endpoint. SocialVerifier resolves (via SocialConfig, @Primary) to
 * CompositeSocialVerifier, which under the project's default config (social.*.mode=mock for
 * google/kakao/naver; toss is unconditionally mock) delegates every provider to
 * MockSocialVerifier -- a deterministic in-process mock with zero network calls. If a test
 * environment sets SOCIAL_{GOOGLE,KAKAO,NAVER}_MODE=real, google/kakao/naver would call
 * hardcoded external hostnames (not property-overridable) that WireMock (localhost-only)
 * cannot intercept; that path is untestable via WireMock per the pipeline's own fallback rule
 * and is out of scope here.
 */
@TestInstance(TestInstance.Lifecycle.PER_METHOD)
@Execution(ExecutionMode.CONCURRENT)
class AuthLoginBlackBoxTest {

    private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8081");

    private static final String DB_URL = System.getProperty("test.db.url", "jdbc:mysql://localhost:3306/authuser");
    private static final String DB_USER = System.getProperty("test.db.user", "root");
    private static final String DB_PASSWORD = System.getProperty("test.db.password", "rootpw");

    private static final String REDIS_URL = System.getProperty("test.redis.url", "redis://localhost:6379/0");

    private static final String UUID_PATTERN =
            "^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$";

    private static Connection getDbConnection() throws Exception {
        return DriverManager.getConnection(DB_URL, DB_USER, DB_PASSWORD);
    }

    // 메서드별 고유 ID 생성 (결정적 — 메서드명 기반)
    private String testId(TestInfo info) {
        return String.format("T%09d",
                Math.abs(info.getTestMethod().get().getName().hashCode()) % 1_000_000_000);
    }

    private static void executeSqlTemplate(String resourcePath, Map<String, String> params) {
        try (Connection conn = getDbConnection();
             InputStream is = AuthLoginBlackBoxTest.class
                     .getClassLoader().getResourceAsStream(resourcePath)) {
            String sql = new String(is.readAllBytes(), StandardCharsets.UTF_8);
            for (var entry : params.entrySet()) {
                sql = sql.replace("${" + entry.getKey() + "}", entry.getValue());
            }
            try (var stmt = conn.createStatement()) {
                for (String line : sql.split("\n")) {
                    String trimmed = line.trim();
                    if (trimmed.startsWith("--") || trimmed.isEmpty()) continue;
                    if (trimmed.endsWith(";")) trimmed = trimmed.substring(0, trimmed.length() - 1);
                    if (!trimmed.isEmpty()) stmt.execute(trimmed);
                }
            }
        } catch (Exception e) {
            throw new RuntimeException("SQL template execution failed: " + resourcePath, e);
        }
    }

    private static int countUserAccount(String provider, String externalId) throws Exception {
        try (Connection conn = getDbConnection();
             PreparedStatement ps = conn.prepareStatement(
                     "SELECT COUNT(*) AS c FROM user_account WHERE social_provider = ? AND external_id = ?")) {
            ps.setString(1, provider);
            ps.setString(2, externalId);
            ResultSet rs = ps.executeQuery();
            assertTrue(rs.next());
            return rs.getInt("c");
        }
    }

    private static String findUserAccountId(String provider, String externalId) throws Exception {
        try (Connection conn = getDbConnection();
             PreparedStatement ps = conn.prepareStatement(
                     "SELECT id FROM user_account WHERE social_provider = ? AND external_id = ?")) {
            ps.setString(1, provider);
            ps.setString(2, externalId);
            ResultSet rs = ps.executeQuery();
            assertTrue(rs.next());
            return rs.getString("id");
        }
    }

    /** Redis 에 저장된 accessToken -> userId 매핑을 직접(raw Lettuce client) 검증. Spring 빈 사용 안 함. */
    private static String redisGetTokenUserId(String accessToken) {
        RedisClient client = RedisClient.create(REDIS_URL);
        try (StatefulRedisConnection<String, String> conn = client.connect()) {
            return conn.sync().get("auth:token:" + accessToken);
        } finally {
            client.shutdown();
        }
    }

    private static long redisGetTokenTtl(String accessToken) {
        RedisClient client = RedisClient.create(REDIS_URL);
        try (StatefulRedisConnection<String, String> conn = client.connect()) {
            return conn.sync().ttl("auth:token:" + accessToken);
        } finally {
            client.shutdown();
        }
    }

    // ------------------------------------------------------------------
    // NTC — Happy Path
    // ------------------------------------------------------------------

    @Test
    void NTC_login_newUser_google_createsAccountAndIssuesToken(TestInfo info) throws Exception {
        String id = testId(info);
        String provider = "google";
        String externalId = provider + ":" + id;
        Map<String, String> params = Map.of("PROVIDER", provider, "EXTERNAL_ID", externalId);

        executeSqlTemplate("sql/auth-login-teardown.sql", params); // defensive, idempotent

        try {
            var resp = given().log().all()
                    .baseUri(BASE_URL)
                    .contentType(ContentType.JSON)
                    .body("{\"provider\":\"" + provider + "\",\"providerToken\":\"valid-" + provider + "-" + id + "\"}")
                    .when()
                    .post("/api/v1/auth/login")
                    .then().log().all()
                    .statusCode(200)
                    .body("accessToken", matchesPattern(UUID_PATTERN))
                    .body("displayName", equalTo("익명"))
                    .extract().response();

            assertEquals(1, countUserAccount(provider, externalId));
            String userId = findUserAccountId(provider, externalId);

            String accessToken = resp.jsonPath().getString("accessToken");
            assertEquals(userId, redisGetTokenUserId(accessToken));
            long ttl = redisGetTokenTtl(accessToken);
            assertTrue(ttl > 0 && ttl <= 3600);
        } finally {
            executeSqlTemplate("sql/auth-login-teardown.sql", params);
        }
    }

    @Test
    void NTC_login_existingUser_kakao_reusesAccount_noDuplicateRow(TestInfo info) throws Exception {
        String id = testId(info);
        String provider = "kakao";
        String externalId = provider + ":" + id;
        String presetUserId = "preset-" + id;
        Map<String, String> params = Map.of(
                "ID", presetUserId, "PROVIDER", provider, "EXTERNAL_ID", externalId);

        executeSqlTemplate("sql/auth-login-teardown.sql", params); // defensive
        executeSqlTemplate("sql/auth-login-setup.sql", params);

        try {
            var resp = given().log().all()
                    .baseUri(BASE_URL)
                    .contentType(ContentType.JSON)
                    .body("{\"provider\":\"" + provider + "\",\"providerToken\":\"valid-" + provider + "-" + id + "\"}")
                    .when()
                    .post("/api/v1/auth/login")
                    .then().log().all()
                    .statusCode(200)
                    .body("accessToken", matchesPattern(UUID_PATTERN))
                    .body("displayName", equalTo("익명"))
                    .extract().response();

            // 재사용: 새 row 생성 없이 정확히 1건, id 는 preset 값 그대로여야 함
            assertEquals(1, countUserAccount(provider, externalId));
            assertEquals(presetUserId, findUserAccountId(provider, externalId));

            String accessToken = resp.jsonPath().getString("accessToken");
            assertEquals(presetUserId, redisGetTokenUserId(accessToken));
        } finally {
            executeSqlTemplate("sql/auth-login-teardown.sql", params);
        }
    }

    @Test
    void NTC_login_newUser_naver_createsAccountAndIssuesToken(TestInfo info) throws Exception {
        String id = testId(info);
        String provider = "naver";
        String externalId = provider + ":" + id;
        Map<String, String> params = Map.of("PROVIDER", provider, "EXTERNAL_ID", externalId);

        executeSqlTemplate("sql/auth-login-teardown.sql", params);

        try {
            given().log().all()
                    .baseUri(BASE_URL)
                    .contentType(ContentType.JSON)
                    .body("{\"provider\":\"" + provider + "\",\"providerToken\":\"valid-" + provider + "-" + id + "\"}")
                    .when()
                    .post("/api/v1/auth/login")
                    .then().log().all()
                    .statusCode(200)
                    .body("accessToken", matchesPattern(UUID_PATTERN))
                    .body("displayName", equalTo("익명"));

            assertEquals(1, countUserAccount(provider, externalId));
        } finally {
            executeSqlTemplate("sql/auth-login-teardown.sql", params);
        }
    }

    @Test
    void NTC_login_toss_alwaysUsesMockRegardlessOfConfig(TestInfo info) throws Exception {
        String id = testId(info);
        String provider = "toss";
        String externalId = provider + ":" + id;
        Map<String, String> params = Map.of("PROVIDER", provider, "EXTERNAL_ID", externalId);

        executeSqlTemplate("sql/auth-login-teardown.sql", params);

        try {
            given().log().all()
                    .baseUri(BASE_URL)
                    .contentType(ContentType.JSON)
                    .body("{\"provider\":\"" + provider + "\",\"providerToken\":\"valid-" + provider + "-" + id + "\"}")
                    .when()
                    .post("/api/v1/auth/login")
                    .then().log().all()
                    .statusCode(200)
                    .body("accessToken", matchesPattern(UUID_PATTERN))
                    .body("displayName", equalTo("익명"));

            assertEquals(1, countUserAccount(provider, externalId));
        } finally {
            executeSqlTemplate("sql/auth-login-teardown.sql", params);
        }
    }

    // ------------------------------------------------------------------
    // ATC — Business exceptions (SocialVerifier -> InvalidTokenException -> 401)
    // ------------------------------------------------------------------

    @Test
    void ATC_login_unsupportedProvider_returns401InvalidToken(TestInfo info) {
        String id = testId(info);
        given().log().all()
                .baseUri(BASE_URL)
                .contentType(ContentType.JSON)
                .body("{\"provider\":\"facebook\",\"providerToken\":\"valid-facebook-" + id + "\"}")
                .when()
                .post("/api/v1/auth/login")
                .then().log().all()
                .statusCode(401)
                .contentType(containsString("application/problem+json"))
                .body("title", equalTo("Invalid token"))
                .body("detail", equalTo("unsupported provider: facebook"));
    }

    @Test
    void ATC_login_malformedToken_returns401InvalidToken(TestInfo info) {
        given().log().all()
                .baseUri(BASE_URL)
                .contentType(ContentType.JSON)
                .body("{\"provider\":\"kakao\",\"providerToken\":\"not-the-right-format\"}")
                .when()
                .post("/api/v1/auth/login")
                .then().log().all()
                .statusCode(401)
                .contentType(containsString("application/problem+json"))
                .body("title", equalTo("Invalid token"))
                .body("detail", equalTo("malformed token for provider: kakao"));
    }

    @Test
    void ATC_login_emptySeed_returns401InvalidToken(TestInfo info) {
        given().log().all()
                .baseUri(BASE_URL)
                .contentType(ContentType.JSON)
                .body("{\"provider\":\"naver\",\"providerToken\":\"valid-naver-\"}")
                .when()
                .post("/api/v1/auth/login")
                .then().log().all()
                .statusCode(401)
                .contentType(containsString("application/problem+json"))
                .body("title", equalTo("Invalid token"))
                .body("detail", equalTo("empty seed"));
    }

    // ------------------------------------------------------------------
    // VTC — Bean validation (@NotBlank on provider / providerToken) -> 400
    // Only status + content-type asserted: framework-default ProblemDetail handler
    // (spring.mvc.problemdetails.enabled=true) shadows the custom handler for 400s,
    // so exact title/detail text is not reliably attributable to this app's code.
    // ------------------------------------------------------------------

    @Test
    void VTC_provider_NULL(TestInfo info) {
        String id = testId(info);
        given().log().all()
                .baseUri(BASE_URL)
                .contentType(ContentType.JSON)
                .body("{\"providerToken\":\"valid-google-" + id + "\"}")
                .when()
                .post("/api/v1/auth/login")
                .then().log().all()
                .statusCode(400)
                .contentType(containsString("application/problem+json"));
    }

    @Test
    void VTC_provider_EMPTY(TestInfo info) {
        String id = testId(info);
        given().log().all()
                .baseUri(BASE_URL)
                .contentType(ContentType.JSON)
                .body("{\"provider\":\"\",\"providerToken\":\"valid-google-" + id + "\"}")
                .when()
                .post("/api/v1/auth/login")
                .then().log().all()
                .statusCode(400)
                .contentType(containsString("application/problem+json"));
    }

    @Test
    void VTC_provider_WHITE_SPACE(TestInfo info) {
        String id = testId(info);
        given().log().all()
                .baseUri(BASE_URL)
                .contentType(ContentType.JSON)
                .body("{\"provider\":\"   \",\"providerToken\":\"valid-google-" + id + "\"}")
                .when()
                .post("/api/v1/auth/login")
                .then().log().all()
                .statusCode(400)
                .contentType(containsString("application/problem+json"));
    }

    @Test
    void VTC_providerToken_NULL() {
        given().log().all()
                .baseUri(BASE_URL)
                .contentType(ContentType.JSON)
                .body("{\"provider\":\"google\"}")
                .when()
                .post("/api/v1/auth/login")
                .then().log().all()
                .statusCode(400)
                .contentType(containsString("application/problem+json"));
    }

    @Test
    void VTC_providerToken_EMPTY() {
        given().log().all()
                .baseUri(BASE_URL)
                .contentType(ContentType.JSON)
                .body("{\"provider\":\"google\",\"providerToken\":\"\"}")
                .when()
                .post("/api/v1/auth/login")
                .then().log().all()
                .statusCode(400)
                .contentType(containsString("application/problem+json"));
    }

    @Test
    void VTC_providerToken_WHITE_SPACE() {
        given().log().all()
                .baseUri(BASE_URL)
                .contentType(ContentType.JSON)
                .body("{\"provider\":\"google\",\"providerToken\":\"   \"}")
                .when()
